--
-- Table structure for table `bulkuploadstaging`
--

DROP TABLE IF EXISTS `bulkuploadstaging`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bulkuploadstaging` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `file_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `original_row_data` longtext COLLATE utf8mb4_unicode_ci,
  `mapped_data` longtext COLLATE utf8mb4_unicode_ci,
  `claimed_by_id` int(11) DEFAULT NULL,
  `moved_at` datetime DEFAULT NULL,
  `moved_to_calltracker` tinyint(1) NOT NULL DEFAULT '0',
  `product_id` int(11) DEFAULT NULL,
  `alternate_mobile_number` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_potential` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `call_status_id` int(11) DEFAULT NULL,
  `company_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contact_person_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date` datetime DEFAULT NULL,
  `designation` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_address` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_status_id` int(11) DEFAULT NULL,
  `industry_id` int(11) DEFAULT NULL,
  `linkedin_sent` tinyint(1) NOT NULL DEFAULT '0',
  `location` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile_no` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `moved_to_quad` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `next_follow_up_date` datetime DEFAULT NULL,
  `personal_email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `source_of_db_id` int(11) DEFAULT NULL,
  `has_validation_error` tinyint(1) NOT NULL DEFAULT '0',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `BulkUploadStaging_claimed_by_id_fkey` (`claimed_by_id`),
  KEY `BulkUploadStaging_user_id_idx` (`user_id`),
  KEY `BulkUploadStaging_mobile_no_idx` (`mobile_no`),
  KEY `BulkUploadStaging_email_address_idx` (`email_address`),
  KEY `BulkUploadStaging_moved_to_calltracker_idx` (`moved_to_calltracker`),
  KEY `BulkUploadStaging_industry_id_fkey` (`industry_id`),
  KEY `BulkUploadStaging_source_of_db_id_fkey` (`source_of_db_id`),
  KEY `BulkUploadStaging_email_status_id_fkey` (`email_status_id`),
  KEY `BulkUploadStaging_call_status_id_fkey` (`call_status_id`),
  KEY `BulkUploadStaging_product_id_idx` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6814 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

