  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `product_id` int(11) DEFAULT NULL,
  `industry_id` int(11) DEFAULT NULL,
  `lead_source_id` int(11) DEFAULT NULL,
  `source_of_db_id` int(11) DEFAULT NULL,
  `company_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `location` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contact_person_name` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designation` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_address` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile_no` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `business_potential` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email_status_id` int(11) DEFAULT NULL,
  `linkedin_sent` tinyint(1) NOT NULL DEFAULT '0',
  `call_status_id` int(11) DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `next_follow_up_date` datetime(3) DEFAULT NULL,
  `moved_to_quad` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pipeline_action` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quadrant_moved_date` datetime(3) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `is_converted` tinyint(1) NOT NULL DEFAULT '0',
  `converted_at` datetime(3) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  `eit_service_id` int(11) DEFAULT NULL,
  `im_service_id` int(11) DEFAULT NULL,
  `product_or_service` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `service_department` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `CallTracker_product_id_fkey` (`product_id`),
  KEY `CallTracker_eit_service_id_fkey` (`eit_service_id`),
  KEY `CallTracker_im_service_id_fkey` (`im_service_id`),
  KEY `CallTracker_industry_id_fkey` (`industry_id`),
  KEY `CallTracker_source_of_db_id_fkey` (`source_of_db_id`),
  KEY `CallTracker_email_status_id_fkey` (`email_status_id`),
  KEY `CallTracker_call_status_id_fkey` (`call_status_id`),
  KEY `idx_calltracker_lead_source_id` (`lead_source_id`),
  CONSTRAINT `fk_calltracker_lead_source` FOREIGN KEY (`lead_source_id`) REFERENCES `leadsource` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1656 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
