--
-- Table structure for table `lead_milestone`
--

DROP TABLE IF EXISTS `lead_milestone`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `lead_milestone` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `lead_id` int(11) NOT NULL,
  `payment_type_id` int(11) DEFAULT NULL,
  `percentage` decimal(5,2) DEFAULT NULL,
  `expected_amount` decimal(15,2) DEFAULT NULL,
  `actual_amount` decimal(15,2) DEFAULT NULL,
  `edc` datetime(3) DEFAULT NULL,
  `revised_edc` datetime(3) DEFAULT NULL,
  `bant_poa` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bant_poa_edc` datetime(3) DEFAULT NULL,
  `poa_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending',
  `collection_status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending',
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Yet To Start',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `lead_milestone_lead_id_fkey` (`lead_id`),
