DROP TABLE IF EXISTS `leadquadranthistory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `leadquadranthistory` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `lead_id` int(11) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `old_quadrant` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `new_quadrant` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `movement_type` enum('AUTO','MANUAL') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MANUAL',
  `moved_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `trigger_days` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `LeadQuadrantHistory_user_id_moved_at_idx` (`user_id`,`moved_at`),
  KEY `LeadQuadrantHistory_old_quadrant_new_quadrant_idx` (`old_quadrant`,`new_quadrant`)
) ENGINE=InnoDB AUTO_INCREMENT=714 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

