INSERT INTO `renewal_notification_template` VALUES (1,'Trinetra Renewal Reminder - FMS License','REMINDER','EMAIL','Renewal Reminder: Your FMS Software License is about to expire','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Renewal Reminder</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:18px;font-weight:normal;\">Your FMS Software License is about to expire.</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;font-weight:bold;\">M/s. {{company_name}}</p>\n  <p style=\"margin:10px 0;\">FMS software license details are listed below and the due for renewal within next <strong>40 Days</strong>.</p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;text-align:center;border-color:#b0c4de;margin:15px 0;\">\n    <tr bgcolor=\"#e6e6e6\" style=\"color:#000;font-weight:bold;\">\n      <th>Service</th>\n      <th>Device Id</th>\n      <th>No. of Device</th>\n      <th>Unit Cost (Rs.)</th>\n      <th>Subtotal (Rs.)</th>\n      <th>GST @18%</th>\n      <th>Total (Rs.)</th>\n      <th>Expiry Date</th>\n      <th>Term</th>\n      <th>Days To Expiry</th>\n    </tr>\n    <tr>\n      <td align=\"left\">Trinetra FMS Software License Usage Charges for Vehicle Tracking Device</td>\n      <td>{{device_id}}</td>\n      <td>{{quantity}}</td>\n      <td>{{unit_cost}}</td>\n      <td>{{subtotal}}</td>\n      <td>{{gst}}</td>\n      <td>{{total}}</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{expiry_date}}</td>\n      <td>Yearly</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{days_left}} Day(s)</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:12px 0;font-size:12px;\">Please find the attached Order Form for Trinetra FMS Software License Renewal and kindly request you to send the order form duly signed along with the payment</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Bank details for online payment transfer:</u></p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;border-color:#b0c4de;margin-bottom:15px;\">\n    <tr bgcolor=\"#cccccc\">\n      <th colspan=\"2\" style=\"text-align:center;font-size:12px;text-transform:uppercase;\">TRINETRA BANK DETAILS</th>\n    </tr>\n    <tr>\n      <td width=\"30%\" style=\"font-weight:bold;\">Company Name</td>\n      <td>TRINETRA Wireless Pvt Ltd</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Name of Bank</td>\n      <td>State Bank of India</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Bank Branch Name</td>\n      <td>Red Fields Branch</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Branch Address</td>\n      <td>1114C, Trichy Road, Coimbatore - 641 045. India.</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">IFSC CODE</td>\n      <td>SBIN0006577</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Account Number</td>\n      <td>30995705595</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:10px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Offline payment:</u></p>\n  <p style=\"margin:5px 0;font-size:12px;\">You can make the payment via Cheque or Demand draft in the name of TRINETRA Wireless Pvt Ltd</p>\n  <p style=\"margin:10px 0;font-size:12px;\">Kindly do the needful.</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;font-weight:bold;\">What if I don\'t renew the services?</p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>1 Your Trinetra FMS account will be deactivated automatically and you may not be able to view the application.</strong></p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>2 If the software license has not been renewed before the due date, your license will be deactivated and for reactivation additional charges has to be paid.</strong></p>\n</div>',NULL,NULL,1,NULL,NULL,NULL,0,1,'2026-08-03 04:50:53.000','2026-08-04 04:12:52.467'),(2,'Trinetra Renewal Deactivation Notice','URGENT','EMAIL','Deactivation Notice: Your services are about to deactivate..','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Deactivation Notice</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:18px;font-weight:normal;\">Your services are about to deactivate..</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;\">The services listed below will be deactivated soon.</p>\n  <p style=\"margin:10px 0;\">Kindly renew them to avoid deactivation</p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;text-align:center;border-color:#b0c4de;margin:15px 0;\">\n    <tr bgcolor=\"#e6e6e6\" style=\"color:#000;font-weight:bold;\">\n      <th>Service</th>\n      <th>Device Id</th>\n      <th>No. of Device</th>\n      <th>Unit Cost (Rs.)</th>\n      <th>Subtotal (Rs.)</th>\n      <th>GST @18%</th>\n      <th>Total (Rs.)</th>\n      <th>Expiry Date</th>\n      <th>Term</th>\n      <th>Days To Expiry</th>\n    </tr>\n    <tr>\n      <td align=\"left\">{{service_name}}</td>\n      <td>{{device_id}}</td>\n      <td>{{quantity}}</td>\n      <td>{{unit_cost}}</td>\n      <td>{{subtotal}}</td>\n      <td>{{gst}}</td>\n      <td>{{total}}</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{expiry_date}}</td>\n      <td>Yearly</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{days_left}} Day(s)</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Bank details for online payment transfer:</u></p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;border-color:#b0c4de;margin-bottom:15px;\">\n    <tr bgcolor=\"#cccccc\">\n      <th colspan=\"2\" style=\"text-align:center;font-size:12px;text-transform:uppercase;\">TRINETRA BANK DETAILS</th>\n    </tr>\n    <tr>\n      <td width=\"30%\" style=\"font-weight:bold;\">Company Name</td>\n      <td>TRINETRA Wireless Pvt Ltd</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Name of Bank</td>\n      <td>State Bank of India</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Bank Branch Name</td>\n      <td>Red Fields Branch</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Branch Address</td>\n      <td>1114C, Trichy Road, Coimbatore - 641 045. India.</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">IFSC CODE</td>\n      <td>SBIN0006577</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Account Number</td>\n      <td>30995705595</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:10px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Offline payment:</u></p>\n  <p style=\"margin:5px 0;font-size:12px;\">You can make the payment via Cheque or Demand draft in the name of TRINETRA Wireless Pvt Ltd</p>\n  <p style=\"margin:10px 0;font-size:12px;\">Kindly do the needful.</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;font-weight:bold;\">What if I don\'t renew the services?</p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>1 Your Trinetra FMS account will be deactivated automatically and you may not be able to view the application.</strong></p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>2 If the software license has not been renewed before the due date, your license will be deactivated and for reactivation additional charges has to be paid.</strong></p>\n</div>',NULL,NULL,1,NULL,NULL,NULL,0,1,'2026-08-03 04:50:53.000','2026-08-04 04:12:52.714'),(3,'Trinetra Renewal Suspension Notice','CRITICAL','EMAIL','URGENT: Suspension Notice — Your Trinetra GPS software license has been suspended','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Suspension Notice</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:16px;font-weight:normal;\">Your Trinetra GPS vehicle tracking software license has been suspended.</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;\">This is to inform you that your service has now been suspended.</p>\n  <p style=\"margin:10px 0;\">The details of the suspended service are as given below:</p>\n\n  <div style=\"margin:15px 0;font-size:13px;line-height:1.8;\">\n    <strong>Product/Service :</strong> {{service_name}}<br/>\n    <strong>Due Date :</strong> {{expiry_date}}<br/>\n    <strong>Suspension Reason :</strong> Due to Non Payment\n  </div>\n\n  <p style=\"margin:15px 0 5px 0;font-size:13px;font-weight:bold;\">How do I reactivate my service?</p>\n  <p style=\"margin:5px 0;font-size:12px;\">In order to get this service reactivated, kindly drop a mail to <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;\">renewals@trinetrawireless.com</a> as soon as possible and confirm payment expected date for renewal.</p>\n\n  <p style=\"margin:12px 0;font-size:12px;color:#cc0000;\"><strong>IMPORTANT : Please note that in case your services are not reactivated, then we will have to remove your data from our system and we will not be responsible for any data loss thereafter.</strong></p>\n\n  <p style=\"margin:12px 0;font-size:12px;\">If you\'ve any feedback or queries, please let us know by replying to this mail. Your feedback will help us in improving our support system.</p>\n\n  <div style=\"margin-top:25px;\">\n    <span style=\"color:#1d4ed8;font-weight:bold;font-size:12px;\">Need help?</span>\n    <table width=\"100%\" style=\"margin-top:8px;\">\n      <tr>\n        <td width=\"48%\" style=\"border:1px solid #000;padding:8px 12px;text-align:center;font-weight:bold;font-size:12px;\">Call: 91-0422-2321307</td>\n        <td width=\"4%\"></td>\n        <td width=\"48%\" style=\"border:1px solid #000;padding:8px 12px;text-align:center;font-weight:bold;font-size:12px;\">e-mail: renewals@trinetrawireless.com</td>\n      </tr>\n    </table>\n  </div>\n</div>',NULL,NULL,1,NULL,NULL,NULL,0,1,'2026-08-03 04:50:53.000','2026-08-04 04:12:52.840'),(4,'Trinetra Renewal Reminder - iWay License','REMINDER','EMAIL','Renewal Reminder: Your Trinetra iWay services are about to expire','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Renewal Reminder</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:18px;font-weight:normal;\">Your services are about to expire.</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;\">The services listed below are due for renewal within next <strong>45 Days</strong>.</p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;text-align:center;border-color:#b0c4de;margin:15px 0;\">\n    <tr bgcolor=\"#e6e6e6\" style=\"color:#000;font-weight:bold;\">\n      <th>Service</th>\n      <th>Device Id</th>\n      <th>No. of Device</th>\n      <th>Unit Cost (Rs.)</th>\n      <th>Subtotal (Rs.)</th>\n      <th>GST @18%</th>\n      <th>Total (Rs.)</th>\n      <th>Expiry Date</th>\n      <th>Term</th>\n      <th>Days To Expiry</th>\n    </tr>\n    <tr>\n      <td align=\"left\">Trinetra iWay Software License Usage Charges for Vehicle Tracking Device</td>\n      <td>{{device_id}}</td>\n      <td>{{quantity}}</td>\n      <td>{{unit_cost}}</td>\n      <td>{{subtotal}}</td>\n      <td>{{gst}}</td>\n      <td>{{total}}</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{expiry_date}}</td>\n      <td>Yearly</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{days_left}} Day(s)</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:12px 0;font-size:12px;\">Please find the attached Order Form for Trinetra iWay Software License Renewal and kindly request you to send the order form duly signed along with the payment</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Bank details for online payment transfer:</u></p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;border-color:#b0c4de;margin-bottom:15px;\">\n    <tr bgcolor=\"#cccccc\">\n      <th colspan=\"2\" style=\"text-align:center;font-size:12px;text-transform:uppercase;\">TRINETRA BANK DETAILS</th>\n    </tr>\n    <tr>\n      <td width=\"30%\" style=\"font-weight:bold;\">Company Name</td>\n      <td>TRINETRA Wireless Pvt Ltd</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Name of Bank</td>\n      <td>State Bank of India</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Bank Branch Name</td>\n      <td>Red Fields Branch</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Branch Address</td>\n      <td>1114C, Trichy Road, Coimbatore - 641 045. India.</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">IFSC CODE</td>\n      <td>SBIN0006577</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Account Number</td>\n      <td>30995705595</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:10px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Offline payment:</u></p>\n  <p style=\"margin:5px 0;font-size:12px;\">You can make the payment via Cheque or Demand draft in the name of TRINETRA Wireless Pvt Ltd</p>\n  <p style=\"margin:10px 0;font-size:12px;\">Kindly do the needful.</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;font-weight:bold;\">What if I don\'t renew the services?</p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>1 Your Trinetra iWay account will be deactivated automatically and you may not be able to view the application.</strong></p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>2 If the software license has not been renewed before the due date, your license will be deactivated and for reactivation additional charges has to be paid.</strong></p>\n</div>',NULL,NULL,1,NULL,NULL,NULL,0,1,'2026-08-03 04:50:53.000','2026-08-04 04:12:52.965'),(5,'ANGLER Order Form & Customer Contract','CONTRACT','EMAIL','ANGLER Order Form & Customer Contract - {{order_number}}','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <h2 style=\"color:#074388;margin-top:0;\">ANGLER Technologies India Pvt Ltd</h2>\n  <p>Dear <strong>{{contact_person}}</strong>,</p>\n  <p>Please find attached the official Order Form & Customer Contract for <strong>{{company_name}}</strong> (Ref # {{order_number}}).</p>\n  <p><strong>Contract Details:</strong><br/>\n  Order Date: {{order_date}}<br/>\n  Total Amount: INR {{total_amount}}<br/>\n  Due Date: {{due_date}}</p>\n  <p>Kindly sign and return a scanned copy of the attached Order Form along with your payment confirmation.</p>\n  <p>Best regards,<br/><strong>ANGLER Renewals Team</strong><br/>support@angleritech.com | +91-422-2312707</p>\n</div>',NULL,NULL,1,NULL,'\n<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<style>\n  body { font-family: Arial, sans-serif; font-size: 11px; color: #000; margin: 0; padding: 15px; }\n  .contract-container { width: 100%; max-width: 800px; margin: 0 auto; border: 1px solid #333; padding: 10px; box-sizing: border-box; }\n  .header-top { display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 5px; font-weight: bold; }\n  .header-top a { color: #0056b3; text-decoration: underline; }\n  .title-banner { background-color: #d9d9d9; text-align: center; font-size: 14px; font-weight: bold; padding: 5px; border: 1px solid #333; margin-bottom: 5px; text-transform: uppercase; letter-spacing: 1px; }\n  \n  table.form-table { width: 100%; border-collapse: collapse; margin-bottom: 5px; }\n  table.form-table td, table.form-table th { border: 1px solid #333; padding: 4px 6px; font-size: 11px; vertical-align: middle; }\n  .bg-grey { background-color: #e9ecef; font-weight: bold; text-align: center; }\n  .bg-light-grey { background-color: #f8f9fa; font-weight: bold; }\n  .text-blue { color: #002060; font-weight: bold; }\n  .text-center { text-align: center; }\n  .text-right { text-align: right; }\n  \n  .terms-section { margin-top: 8px; border: 1px solid #333; padding: 6px; font-size: 9.5px; line-height: 1.35; }\n  .terms-title { font-weight: bold; margin-bottom: 4px; font-size: 10.5px; text-decoration: underline; }\n  .terms-list { margin: 0; padding-left: 0; list-style-type: none; }\n  .terms-list li { margin-bottom: 4px; text-align: justify; }\n\n  .sig-table { width: 100%; border-collapse: collapse; margin-top: 10px; }\n  .sig-table td { border: 1px solid #333; height: 45px; vertical-align: bottom; text-align: center; font-size: 10px; font-weight: bold; padding-bottom: 4px; }\n  \n  .footer-banner { margin-top: 10px; border-top: 2px solid #002060; padding-top: 5px; font-size: 9px; line-height: 1.3; }\n  .footer-logo { font-size: 16px; font-weight: bold; color: #002060; }\n  .footer-row { display: flex; justify-content: space-between; align-items: flex-end; }\n</style>\n</head>\n<body>\n\n<div class=\"contract-container\">\n  <!-- Header Top Links -->\n  <div class=\"header-top\">\n    <span><u>ANGLER Customer Contract</u></span>\n    <span><a href=\"http://www.angleritech.com\" target=\"_blank\">www.angleritech.com</a></span>\n  </div>\n\n  <!-- Title Banner -->\n  <div class=\"title-banner\">ANGLER ORDER FORM</div>\n\n  <!-- Customer & Internal Grid Table -->\n  <table class=\"form-table\">\n    <tr>\n      <td width=\"22%\" class=\"bg-light-grey\">Customer Name</td>\n      <td width=\"43%\" class=\"text-center text-blue\"><strong>{{customer_name}}</strong></td>\n      <td width=\"35%\" colspan=\"2\" class=\"bg-grey\">To be filled by ANGLER Only</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Address</td>\n      <td class=\"text-center\">{{customer_address}}</td>\n      <td width=\"15%\" class=\"bg-light-grey\">Order #</td>\n      <td width=\"20%\" class=\"text-center text-blue\">{{order_number}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">City & Pin Code</td>\n      <td class=\"text-center\">{{customer_city_pincode}}</td>\n      <td class=\"bg-light-grey\">Order Date</td>\n      <td class=\"text-center text-blue\">{{order_date}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Phone No</td>\n      <td class=\"text-center\">{{customer_phone}}</td>\n      <td class=\"bg-light-grey\">Marketing Ref.</td>\n      <td class=\"text-center text-blue\">{{marketing_ref}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Mobile No</td>\n      <td class=\"text-center\">{{customer_mobile}}</td>\n      <td class=\"bg-light-grey\">Mktg SBU</td>\n      <td class=\"text-center text-blue\">{{mktg_sbu}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Email Id</td>\n      <td class=\"text-center text-blue\">{{customer_email}}</td>\n      <td class=\"bg-light-grey\">Mktg Executive</td>\n      <td class=\"text-center text-blue\">{{mktg_executive}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Contact Person</td>\n      <td class=\"text-center\"><strong>{{contact_person}}</strong></td>\n      <td class=\"bg-light-grey\">Tech SBU</td>\n      <td class=\"text-center text-blue\">{{tech_sbu}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Designation</td>\n      <td class=\"text-center\">{{contact_designation}}</td>\n      <td class=\"bg-light-grey\">Tech Vertical</td>\n      <td class=\"text-center text-blue\">{{tech_vertical}}</td>\n    </tr>\n  </table>\n\n  <!-- Services / Features Table -->\n  <table class=\"form-table\">\n    <tr class=\"bg-grey\">\n      <th width=\"30%\">Feature</th>\n      <th width=\"30%\">Description</th>\n      <th width=\"12%\">Duration</th>\n      <th width=\"16%\">Period</th>\n      <th width=\"12%\">Amount<br><span style=\"font-weight:normal;\">In Rs.</span></th>\n    </tr>\n    <tr>\n      <td>1. {{service_title}}</td>\n      <td class=\"text-center\"><a href=\"http://{{domain_url}}\" target=\"_blank\" style=\"color:#0056b3;\">{{domain_url}}</a></td>\n      <td class=\"text-center\">1 year</td>\n      <td class=\"text-center\">{{duration_period}}</td>\n      <td class=\"text-right\">{{subtotal}}</td>\n    </tr>\n    <tr>\n      <td colspan=\"4\" class=\"text-right font-bold bg-light-grey\">Total</td>\n      <td class=\"text-right text-blue\">{{subtotal}}</td>\n    </tr>\n    <tr>\n      <td colspan=\"4\" class=\"text-right font-bold bg-light-grey\">Service Tax / GST @ {{tax_percentage}}</td>\n      <td class=\"text-right text-blue\">{{tax_amount}}</td>\n    </tr>\n    <tr>\n      <td colspan=\"4\" class=\"text-right font-bold bg-light-grey\">Grand Total</td>\n      <td class=\"text-right text-blue\"><strong>{{grand_total}}</strong></td>\n    </tr>\n  </table>\n\n  <!-- Payment Terms Table -->\n  <table class=\"form-table\">\n    <tr>\n      <td width=\"30%\" class=\"bg-light-grey\">PAYMENT TERMS</td>\n      <td width=\"70%\" class=\"text-center\"><strong>{{payment_terms_label}}</strong></td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Payment %</td>\n      <td class=\"text-center\">{{payment_percentage}}</td>\n    </tr>\n    <tr>\n      <td class=\"bg-light-grey\">Total Value in Rs.</td>\n      <td class=\"text-center text-blue\"><strong>{{grand_total}}</strong></td>\n    </tr>\n  </table>\n\n  <!-- Terms and Conditions Block -->\n  <div class=\"terms-section\">\n    <div class=\"terms-title\">Terms and conditions :</div>\n    <ol class=\"terms-list\" style=\"padding-left:14px; list-style-type: decimal;\">\n      <li>This order form is as an authorisation from the said client retaining the services of ANGLER Technologies India Pvt Ltd., (ANGLER) for domain name registration, displaying the client \'s information on the Internet, hosting, designing, software application development and remitting foreign exchange for the same as applicable.</li>\n      <li>Pricing may vary according to the clients demand for extra or special requirements or features, for which a separate order form will have to be issued. Also, prices may vary based on local currency fluctuations and ANGLER has the right to revise recurring pricing yearly depending on change in Domain registration / US server costs.</li>\n      <li>Strict adherence to payment structure will enable ANGLER to provide prompt and effective service. Delayed payment or non-payment of payment charges / dues will lead to project stoppage / automatic account deactivation.</li>\n      <li>Service Tax / GST is applicable and is charged accordingly in the order form. Sales Tax and other taxes at present are nil, if the Government imposes such direct / indirect taxes (other than Service Tax) then same will be applicable over & above quoted price vide our invoice or supplementary invoice and to be paid for by client retrospectively.</li>\n      <li>ANGLER will utilize its best efforts to maintain acceptable performance of services contracted for the various Packages, but ANGLER makes absolutely no warranties whatsoever, express or implied, including warranty of merchantability or fitness for a particular purpose. ANGLER cannot guarantee continuous service, service at any particular time, or integrity of data stored or transmitted via its system or via the Internet.</li>\n      <li>All payments are to be made in the form of Cheque / Demand Draft / NEFT - account payee in favour of ANGLER Technologies India Pvt Ltd., Coimbatore. All payments are non-refundable. All disputes are subject to Coimbatore Jurisdiction only.</li>\n    </ol>\n  </div>\n\n  <!-- Signatures Table -->\n  <table class=\"sig-table\">\n    <tr>\n      <td width=\"50%\">\n        Authorised Signatory<br>\n        <span style=\"font-weight:normal;\">For ANGLER Technologies India Pvt Ltd</span>\n      </td>\n      <td width=\"50%\">\n        Authorised Signatory<br>\n        <span style=\"font-weight:normal;\">For Customer</span>\n      </td>\n    </tr>\n  </table>\n\n  <!-- Official Footer Banner -->\n  <div class=\"footer-banner\">\n    <div class=\"footer-logo\">ANGLER Technologies India Pvt Ltd.,</div>\n    <div class=\"footer-row\">\n      <div>\n        #1247 (Old # 1144) Trichy Road, Coimbatore - 641 045, India<br>\n        <strong>Operations @ USA, CA, UK, UAE, IN, SG, HK, AU</strong><br>\n        <a href=\"mailto:support@angleritech.com\" style=\"color:#0056b3;\">support@angleritech.com</a>\n      </div>\n      <div style=\"text-align:right;\">\n        Tel : +91-422-2312707, 2313938<br>\n        Fax : +91-422-2313936<br>\n        Visit us at : <a href=\"http://www.angleritech.com\" target=\"_blank\" style=\"color:#0056b3;\">www.angleritech.com</a> &nbsp;|&nbsp; Pg. 1/1\n      </div>\n    </div>\n  </div>\n</div>\n\n</body>\n</html>\n',NULL,0,1,'2026-08-03 04:56:28.767','2026-08-04 04:12:53.291');
