INSERT INTO `renewal_template_version` VALUES (1,1,1,'Renewal Reminder: Your FMS Software License is about to expire','',NULL,'Initial published seed version matching official design',NULL,NULL,'2026-08-04 04:12:52','Trinetra Renewal Reminder - FMS License','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Renewal Reminder</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:18px;font-weight:normal;\">Your FMS Software License is about to expire.</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;font-weight:bold;\">M/s. {{company_name}}</p>\n  <p style=\"margin:10px 0;\">FMS software license details are listed below and the due for renewal within next <strong>40 Days</strong>.</p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;text-align:center;border-color:#b0c4de;margin:15px 0;\">\n    <tr bgcolor=\"#e6e6e6\" style=\"color:#000;font-weight:bold;\">\n      <th>Service</th>\n      <th>Device Id</th>\n      <th>No. of Device</th>\n      <th>Unit Cost (Rs.)</th>\n      <th>Subtotal (Rs.)</th>\n      <th>GST @18%</th>\n      <th>Total (Rs.)</th>\n      <th>Expiry Date</th>\n      <th>Term</th>\n      <th>Days To Expiry</th>\n    </tr>\n    <tr>\n      <td align=\"left\">Trinetra FMS Software License Usage Charges for Vehicle Tracking Device</td>\n      <td>{{device_id}}</td>\n      <td>{{quantity}}</td>\n      <td>{{unit_cost}}</td>\n      <td>{{subtotal}}</td>\n      <td>{{gst}}</td>\n      <td>{{total}}</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{expiry_date}}</td>\n      <td>Yearly</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{days_left}} Day(s)</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:12px 0;font-size:12px;\">Please find the attached Order Form for Trinetra FMS Software License Renewal and kindly request you to send the order form duly signed along with the payment</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Bank details for online payment transfer:</u></p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;border-color:#b0c4de;margin-bottom:15px;\">\n    <tr bgcolor=\"#cccccc\">\n      <th colspan=\"2\" style=\"text-align:center;font-size:12px;text-transform:uppercase;\">TRINETRA BANK DETAILS</th>\n    </tr>\n    <tr>\n      <td width=\"30%\" style=\"font-weight:bold;\">Company Name</td>\n      <td>TRINETRA Wireless Pvt Ltd</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Name of Bank</td>\n      <td>State Bank of India</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Bank Branch Name</td>\n      <td>Red Fields Branch</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Branch Address</td>\n      <td>1114C, Trichy Road, Coimbatore - 641 045. India.</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">IFSC CODE</td>\n      <td>SBIN0006577</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Account Number</td>\n      <td>30995705595</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:10px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Offline payment:</u></p>\n  <p style=\"margin:5px 0;font-size:12px;\">You can make the payment via Cheque or Demand draft in the name of TRINETRA Wireless Pvt Ltd</p>\n  <p style=\"margin:10px 0;font-size:12px;\">Kindly do the needful.</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;font-weight:bold;\">What if I don\'t renew the services?</p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>1 Your Trinetra FMS account will be deactivated automatically and you may not be able to view the application.</strong></p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>2 If the software license has not been renewed before the due date, your license will be deactivated and for reactivation additional charges has to be paid.</strong></p>\n</div>'),(2,2,1,'Deactivation Notice: Your services are about to deactivate..','',NULL,'Initial published seed version matching official design',NULL,NULL,'2026-08-04 04:12:52','Trinetra Renewal Deactivation Notice','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Deactivation Notice</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:18px;font-weight:normal;\">Your services are about to deactivate..</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;\">The services listed below will be deactivated soon.</p>\n  <p style=\"margin:10px 0;\">Kindly renew them to avoid deactivation</p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;text-align:center;border-color:#b0c4de;margin:15px 0;\">\n    <tr bgcolor=\"#e6e6e6\" style=\"color:#000;font-weight:bold;\">\n      <th>Service</th>\n      <th>Device Id</th>\n      <th>No. of Device</th>\n      <th>Unit Cost (Rs.)</th>\n      <th>Subtotal (Rs.)</th>\n      <th>GST @18%</th>\n      <th>Total (Rs.)</th>\n      <th>Expiry Date</th>\n      <th>Term</th>\n      <th>Days To Expiry</th>\n    </tr>\n    <tr>\n      <td align=\"left\">{{service_name}}</td>\n      <td>{{device_id}}</td>\n      <td>{{quantity}}</td>\n      <td>{{unit_cost}}</td>\n      <td>{{subtotal}}</td>\n      <td>{{gst}}</td>\n      <td>{{total}}</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{expiry_date}}</td>\n      <td>Yearly</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{days_left}} Day(s)</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Bank details for online payment transfer:</u></p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;border-color:#b0c4de;margin-bottom:15px;\">\n    <tr bgcolor=\"#cccccc\">\n      <th colspan=\"2\" style=\"text-align:center;font-size:12px;text-transform:uppercase;\">TRINETRA BANK DETAILS</th>\n    </tr>\n    <tr>\n      <td width=\"30%\" style=\"font-weight:bold;\">Company Name</td>\n      <td>TRINETRA Wireless Pvt Ltd</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Name of Bank</td>\n      <td>State Bank of India</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Bank Branch Name</td>\n      <td>Red Fields Branch</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Branch Address</td>\n      <td>1114C, Trichy Road, Coimbatore - 641 045. India.</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">IFSC CODE</td>\n      <td>SBIN0006577</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Account Number</td>\n      <td>30995705595</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:10px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Offline payment:</u></p>\n  <p style=\"margin:5px 0;font-size:12px;\">You can make the payment via Cheque or Demand draft in the name of TRINETRA Wireless Pvt Ltd</p>\n  <p style=\"margin:10px 0;font-size:12px;\">Kindly do the needful.</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;font-weight:bold;\">What if I don\'t renew the services?</p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>1 Your Trinetra FMS account will be deactivated automatically and you may not be able to view the application.</strong></p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>2 If the software license has not been renewed before the due date, your license will be deactivated and for reactivation additional charges has to be paid.</strong></p>\n</div>'),(3,3,1,'URGENT: Suspension Notice — Your Trinetra GPS software license has been suspended','',NULL,'Initial published seed version matching official design',NULL,NULL,'2026-08-04 04:12:52','Trinetra Renewal Suspension Notice','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Suspension Notice</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:16px;font-weight:normal;\">Your Trinetra GPS vehicle tracking software license has been suspended.</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;\">This is to inform you that your service has now been suspended.</p>\n  <p style=\"margin:10px 0;\">The details of the suspended service are as given below:</p>\n\n  <div style=\"margin:15px 0;font-size:13px;line-height:1.8;\">\n    <strong>Product/Service :</strong> {{service_name}}<br/>\n    <strong>Due Date :</strong> {{expiry_date}}<br/>\n    <strong>Suspension Reason :</strong> Due to Non Payment\n  </div>\n\n  <p style=\"margin:15px 0 5px 0;font-size:13px;font-weight:bold;\">How do I reactivate my service?</p>\n  <p style=\"margin:5px 0;font-size:12px;\">In order to get this service reactivated, kindly drop a mail to <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;\">renewals@trinetrawireless.com</a> as soon as possible and confirm payment expected date for renewal.</p>\n\n  <p style=\"margin:12px 0;font-size:12px;color:#cc0000;\"><strong>IMPORTANT : Please note that in case your services are not reactivated, then we will have to remove your data from our system and we will not be responsible for any data loss thereafter.</strong></p>\n\n  <p style=\"margin:12px 0;font-size:12px;\">If you\'ve any feedback or queries, please let us know by replying to this mail. Your feedback will help us in improving our support system.</p>\n\n  <div style=\"margin-top:25px;\">\n    <span style=\"color:#1d4ed8;font-weight:bold;font-size:12px;\">Need help?</span>\n    <table width=\"100%\" style=\"margin-top:8px;\">\n      <tr>\n        <td width=\"48%\" style=\"border:1px solid #000;padding:8px 12px;text-align:center;font-weight:bold;font-size:12px;\">Call: 91-0422-2321307</td>\n        <td width=\"4%\"></td>\n        <td width=\"48%\" style=\"border:1px solid #000;padding:8px 12px;text-align:center;font-weight:bold;font-size:12px;\">e-mail: renewals@trinetrawireless.com</td>\n      </tr>\n    </table>\n  </div>\n</div>'),(4,4,1,'Renewal Reminder: Your Trinetra iWay services are about to expire','',NULL,'Initial published seed version matching official design',NULL,NULL,'2026-08-04 04:12:53','Trinetra Renewal Reminder - iWay License','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <table width=\"100%\" style=\"margin-bottom:15px;\">\n    <tr>\n      <td>\n        <div style=\"font-weight:bold;font-size:24px;color:#002060;display:flex;align-items:center;\">\n          <span style=\"color:#f59e0b;font-size:28px;margin-right:4px;\">●</span>trinetra\n        </div>\n        <div style=\"font-size:11px;color:#555;font-weight:bold;margin-top:2px;\">Fleet Management, Mobility & IoT Solutions</div>\n      </td>\n      <td align=\"right\" style=\"font-size:12px;color:#002060;vertical-align:top;\">\n        <a href=\"mailto:renewals@trinetrawireless.com\" style=\"color:#002060;text-decoration:underline;\">renewals@trinetrawireless.com</a><br/>\n        <strong style=\"font-size:13px;display:inline-block;margin-top:4px;\">+91-422-2321307</strong>\n      </td>\n    </tr>\n  </table>\n\n  <div style=\"background:#0f2942;color:#fff;padding:12px 15px;margin-bottom:15px;\">\n    <h2 style=\"margin:0;font-size:22px;font-weight:normal;\">Renewal Reminder</h2>\n    <h3 style=\"margin:4px 0 0 0;font-size:18px;font-weight:normal;\">Your services are about to expire.</h3>\n  </div>\n\n  <p style=\"margin:10px 0;\">Dear Mr. <strong>{{contact_person}}</strong>,</p>\n  <p style=\"margin:10px 0;\">The services listed below are due for renewal within next <strong>45 Days</strong>.</p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;text-align:center;border-color:#b0c4de;margin:15px 0;\">\n    <tr bgcolor=\"#e6e6e6\" style=\"color:#000;font-weight:bold;\">\n      <th>Service</th>\n      <th>Device Id</th>\n      <th>No. of Device</th>\n      <th>Unit Cost (Rs.)</th>\n      <th>Subtotal (Rs.)</th>\n      <th>GST @18%</th>\n      <th>Total (Rs.)</th>\n      <th>Expiry Date</th>\n      <th>Term</th>\n      <th>Days To Expiry</th>\n    </tr>\n    <tr>\n      <td align=\"left\">Trinetra iWay Software License Usage Charges for Vehicle Tracking Device</td>\n      <td>{{device_id}}</td>\n      <td>{{quantity}}</td>\n      <td>{{unit_cost}}</td>\n      <td>{{subtotal}}</td>\n      <td>{{gst}}</td>\n      <td>{{total}}</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{expiry_date}}</td>\n      <td>Yearly</td>\n      <td style=\"color:#cc0000;font-weight:bold;\">{{days_left}} Day(s)</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:12px 0;font-size:12px;\">Please find the attached Order Form for Trinetra iWay Software License Renewal and kindly request you to send the order form duly signed along with the payment</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Bank details for online payment transfer:</u></p>\n\n  <table width=\"100%\" border=\"1\" cellspacing=\"0\" cellpadding=\"6\" style=\"border-collapse:collapse;font-size:11px;border-color:#b0c4de;margin-bottom:15px;\">\n    <tr bgcolor=\"#cccccc\">\n      <th colspan=\"2\" style=\"text-align:center;font-size:12px;text-transform:uppercase;\">TRINETRA BANK DETAILS</th>\n    </tr>\n    <tr>\n      <td width=\"30%\" style=\"font-weight:bold;\">Company Name</td>\n      <td>TRINETRA Wireless Pvt Ltd</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Name of Bank</td>\n      <td>State Bank of India</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Bank Branch Name</td>\n      <td>Red Fields Branch</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Branch Address</td>\n      <td>1114C, Trichy Road, Coimbatore - 641 045. India.</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">IFSC CODE</td>\n      <td>SBIN0006577</td>\n    </tr>\n    <tr>\n      <td style=\"font-weight:bold;\">Account Number</td>\n      <td>30995705595</td>\n    </tr>\n  </table>\n\n  <p style=\"margin:10px 0 5px 0;font-size:12px;\"><u style=\"font-weight:bold;\">Offline payment:</u></p>\n  <p style=\"margin:5px 0;font-size:12px;\">You can make the payment via Cheque or Demand draft in the name of TRINETRA Wireless Pvt Ltd</p>\n  <p style=\"margin:10px 0;font-size:12px;\">Kindly do the needful.</p>\n\n  <p style=\"margin:15px 0 5px 0;font-size:12px;font-weight:bold;\">What if I don\'t renew the services?</p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>1 Your Trinetra iWay account will be deactivated automatically and you may not be able to view the application.</strong></p>\n  <p style=\"margin:4px 0;font-size:12px;\"><strong>2 If the software license has not been renewed before the due date, your license will be deactivated and for reactivation additional charges has to be paid.</strong></p>\n</div>'),(5,5,1,'ANGLER Order Form & Customer Contract - {{order_number}}','',NULL,'Initial published seed version matching official design',NULL,NULL,'2026-08-04 04:12:53','ANGLER Order Form & Customer Contract','<div style=\"max-width:750px;margin:0 auto;font-family:Arial,sans-serif;border:1px solid #ccc;padding:20px;background:#fff;color:#000;\">\n  <h2 style=\"color:#074388;margin-top:0;\">ANGLER Technologies India Pvt Ltd</h2>\n  <p>Dear <strong>{{contact_person}}</strong>,</p>\n  <p>Please find attached the official Order Form & Customer Contract for <strong>{{company_name}}</strong> (Ref # {{order_number}}).</p>\n  <p><strong>Contract Details:</strong><br/>\n  Order Date: {{order_date}}<br/>\n  Total Amount: INR {{total_amount}}<br/>\n  Due Date: {{due_date}}</p>\n  <p>Kindly sign and return a scanned copy of the attached Order Form along with your payment confirmation.</p>\n  <p>Best regards,<br/><strong>ANGLER Renewals Team</strong><br/>support@angleritech.com | +91-422-2312707</p>\n</div>');
